#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzSample_bumpMap(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_bumpMap(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_property;
uniform float amzp_softness;
uniform float amzp_height;
uniform float amzp_displacement;
uniform float amzp_lightType;
uniform float amzp_lightIntensity;
layout(color) uniform half4 amzp_lightColor;
uniform float amzp_lightHeight;
uniform float2 amzp_lightPosition;
uniform float amzp_lightDirection;
uniform float amzp_ambient;
uniform float amzp_diffuse;
uniform float amzp_specular;
uniform float amzp_roughness;
uniform float amzp_metal;
        float getVal(float4 col, int prop) {
            if (prop == 1) return col.r;
            if (prop == 2) return col.g;
            if (prop == 3) return col.b;
            if (prop == 4) return col.a;
            return dot(col.rgb, float3(0.299, 0.587, 0.114));
        }
        void amzRender() {
            float2 uv = amzScreenNorm();
            float soft = max(amzp_softness, 1.0) * 0.001;
            float4 s_left = amzTexture(1, uv + float2(-soft, 0.0));
            float4 s_right = amzTexture(1, uv + float2(soft, 0.0));
            float4 s_up = amzTexture(1, uv + float2(0.0, soft));
            float4 s_down = amzTexture(1, uv + float2(0.0, -soft));
            float v_l = getVal(s_left, int(int(amzp_property)));
            float v_r = getVal(s_right, int(int(amzp_property)));
            float v_u = getVal(s_up, int(int(amzp_property)));
            float v_d = getVal(s_down, int(int(amzp_property)));
            float h_scale = amzp_height * 0.1;
            float3 normal = normalize(float3(v_l - v_r, v_d - v_u, 1.0 / h_scale));
            float2 refractOff = normal.xy * (amzp_displacement * 0.01);
            float4 src = amzTexture(0, uv + refractOff);
            float3 l_dir;
            if (int(amzp_lightType) == 0) {
                float rad = (amzp_lightDirection - 90.0) * (3.14159265359 / 180.0);
                float h_rad = (amzp_lightHeight * 0.9) * (3.14159265359 / 180.0);
                l_dir = normalize(float3(cos(rad) * cos(h_rad), sin(rad) * cos(h_rad), sin(h_rad)));
            } else {
                l_dir = normalize(float3(amzp_lightPosition - uv, amzp_lightHeight * 0.01));
            }
            float3 viewDir = float3(0.0, 0.0, 1.0);
            float3 halfDir = normalize(l_dir + viewDir);
            float diff = max(dot(normal, l_dir), 0.0);
            float spec = pow(max(dot(normal, halfDir), 0.0), 1.0 / max(amzp_roughness, 0.001));
            float3 ambCol = src.rgb * (amzp_ambient * 0.01);
            float3 diffCol = src.rgb * diff * (amzp_diffuse * 0.01) * amzp_lightColor.rgb * (amzp_lightIntensity * 0.01);
            float3 specBase = amzp_lightColor.rgb * spec * (amzp_specular * 0.01) * (amzp_lightIntensity * 0.01);
            float3 specCol = mix(specBase, specBase * src.rgb, amzp_metal * 0.01);
            float3 finalCol = ambCol + diffCol + specCol;
            amzOutput = float4(finalCol, src.a);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

